import { defineEventHandler, defineRoutes, getQuery } from "dsh-tauri";

//#region src/shared/constants.ts
/** 插件唯一标识：同时作为 locale 命名空间、store 存储根与日志前缀。 */
const PLUGIN_ID = "dsh-tauri-notification";

//#endregion
//#region src/host/service/turn-end.ts
/** sessionId → 最近一次回合结束事实（内存态，不落盘）。 */
const facts = /* @__PURE__ */ new Map();
function recordTurnEnd(sessionId, fact) {
	facts.set(sessionId, fact);
}
function turnEndFact(sessionId) {
	return facts.get(sessionId);
}
function clearTurnEndFacts() {
	facts.clear();
}

//#endregion
//#region src/host/events/session-event.ts
/**
* `session/event` 订阅：只挑 `turn/end` 记下结束原因。
*
* 事件回调签名是 `(session, event)`（与 `dsh-tauri-worktree`、`dsh-tauri-pet` 一致），
* 会话 id 取 `session.id`。原因缺失时记成空原因而不是直接返回：空原因在客户端不算中断，
* 于是退化成「照常通知」；直接返回会把上一回合的旧原因留在表里，那个旧原因若是 `aborted`，
* 就会把这一回合的通知也一并吞掉。
*/
function handleSessionEvent(session, event) {
	if (event?.type !== "turn/end") return;
	const sessionId = session?.id;
	if (typeof sessionId !== "string" || sessionId.length === 0) return;
	const reason = event?.data?.reason?.kind;
	const turn = event?.data?.turn;
	recordTurnEnd(sessionId, {
		reason: typeof reason === "string" ? reason : "",
		turn: typeof turn === "number" ? turn : -1
	});
}

//#endregion
//#region src/host/routes/turn-end/get.ts
/**
* `GET /turn-end?sessionId=…`：回答「这个会话的回合为什么结束」。
*
* 查不到就返回空对象（200）而不是 404：调用方（客户端通知）只关心「是不是用户中断」，
* 未知一律按「不是」处理，没必要区分「没记录」与「会话不存在」。
*/
var get_default = defineEventHandler(async (event) => {
	const query = getQuery(event);
	const sessionId = typeof query.sessionId === "string" ? query.sessionId : "";
	if (sessionId.length === 0) return {};
	const fact = turnEndFact(sessionId);
	return fact === void 0 ? {} : {
		reason: fact.reason,
		turn: fact.turn
	};
});

//#endregion
//#region src/host/routes/index.ts
/** 宿主路由：客户端在弹「回合完成」通知前先问一次结束原因。 */
const routes = defineRoutes((disposer) => {
	disposer.get({
		kind: "exact",
		path: "/api/desktop/dsh-tauri-notification/turn-end"
	}, get_default);
});

//#endregion
//#region src/host/apply.ts
function apply(ctx) {
	ctx.on("session/event", handleSessionEvent);
	ctx.effect(() => routes(ctx), `${PLUGIN_ID}: routes`);
	ctx.effect(() => () => clearTurnEndFacts(), `${PLUGIN_ID}: host runtime`);
}

//#endregion
//#region src/index.ts
const name = PLUGIN_ID;
/** 宿主服务依赖：`webServer`（注册路由）与 `connection`（路由鉴权闸门，注册期必需）。 */
const inject = ["webServer", "connection"];

//#endregion
export { apply, inject, name };